&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;Morning, evening or overnight&lt;/span&gt;&lt;/li&gt;
