&lt;p style=&quot;margin-bottom: .0001pt;&quot;&gt;&lt;span style=&quot;color: #000000;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;Details&lt;/span&gt;&lt;/strong&gt;:&amp;nbsp; &amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Location: Kennebunk, ME&lt;/li&gt;
&lt;li&gt;Schedule: Mon- Fri 830-500&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Competitive compensation package&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;ul&gt;
